import{_ as e,o as s,c as o,ae as a}from"./chunks/framework.BzQXgbNp.js";const u=JSON.parse('{"title":"📜 /menu 54-槽位箱子選單 GUI 系統指南","description":"","frontmatter":{},"headers":[],"relativePath":"Mc-Menu-System.md","filePath":"Mc-Menu-System.md"}'),d={name:"Mc-Menu-System.md"};function n(c,t,i,l,r,p){return s(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="📜-menu-54-槽位箱子選單-gui-系統指南" tabindex="-1">📜 /menu 54-槽位箱子選單 GUI 系統指南 <a class="header-anchor" href="#📜-menu-54-槽位箱子選單-gui-系統指南" aria-label="Permalink to &quot;📜 /menu 54-槽位箱子選單 GUI 系統指南&quot;">​</a></h1><p>Craft-Core 提供了全方位視覺化 <strong>54-槽位 (6x9) 箱子選單 GUI 系統</strong>。將模組的所有功能（商店、領地、傳送、任務、懸賞、稱號、假人控制與管理員面板）全數整合於視覺化 GUI 介面中，<strong>同時 100% 完整保留所有原版文字指令</strong>。</p><hr><h2 id="🎮-指令與開啟方式" tabindex="-1">🎮 指令與開啟方式 <a class="header-anchor" href="#🎮-指令與開啟方式" aria-label="Permalink to &quot;🎮 指令與開啟方式&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 開啟 54-槽位選單大廳 GUI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/menu</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 指令別名 (功能完全相同)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/m</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/cd</span></span></code></pre></div><hr><h2 id="🧭-八大主選單分類-54-slot-hub-layout" tabindex="-1">🧭 八大主選單分類 (54-Slot Hub Layout) <a class="header-anchor" href="#🧭-八大主選單分類-54-slot-hub-layout" aria-label="Permalink to &quot;🧭 八大主選單分類 (54-Slot Hub Layout)&quot;">​</a></h2><p>開啟 <code>/menu</code> 主選單後，介面中央將呈現八大功能選單面板：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Row 1 ] 🧱 灰色玻璃板裝飾邊框</span></span>
<span class="line"><span>[ Row 2 ] 🏪[10] 商店管理    🛡️[12] 領地/密碼鎖   🧭[14] 傳送與家園   ⚔️[16] 任務與懸賞</span></span>
<span class="line"><span>[ Row 3 ] 🧱 裝飾分隔</span></span>
<span class="line"><span>[ Row 4 ] 🎰[28] 福利與稱號  🤖[30] 假人控制台    🏭[32] 機器認證    🛠️[34] 管理員面板 (OP專屬)</span></span>
<span class="line"><span>[ Row 5 ] 🧱 裝飾分隔</span></span>
<span class="line"><span>[ Row 6 ] ❌[49] 關閉選單</span></span></code></pre></div><table tabindex="0"><thead><tr><th>圖示按鈕</th><th>類別名稱</th><th>點擊動作與子選單功能</th></tr></thead><tbody><tr><td>🏪 <code>Slot 10</code></td><td><strong>商店管理系統</strong></td><td>導向遠端商店遙控 (<code>/shop control</code>)，查看全服擺攤、庫存與營收。</td></tr><tr><td>🛡️ <code>Slot 12</code></td><td><strong>領地與密碼箱</strong></td><td>導向領地列表 (<code>/claim list</code>)，查看領地座標、權限設定與保險箱。</td></tr><tr><td>🧭 <code>Slot 14</code></td><td><strong>傳送與家園</strong></td><td>列表展出個人所有家點 (<code>/home</code>)、公共地標 (<code>/warp</code>)、一鍵隨機傳送 (<code>/rtp</code>) 與返回死亡地點 (<code>/back</code>)。</td></tr><tr><td>⚔️ <code>Slot 16</code></td><td><strong>任務與懸賞</strong></td><td>查看每日任務 (<code>/task</code>)、全服每週大目標 (<code>/bounty</code>) 進度條與野外藏寶圖線索 (<code>/treasure</code>)。</td></tr><tr><td>🎰 <code>Slot 28</code></td><td><strong>福利與頭頂稱號</strong></td><td>直觀列出所有已解鎖頭頂稱號，<strong>點擊即時佩戴/切換</strong> (<code>/title</code>)。</td></tr><tr><td>🤖 <code>Slot 30</code></td><td><strong>假人 (Bot) 控制台</strong></td><td>一鍵召喚新假人、一鍵開啟假人 54-槽位背包 (<code>/invsee</code>)、切換自動打怪或解散假人。</td></tr><tr><td>🏭 <code>Slot 32</code></td><td><strong>機器認證與免領地費</strong></td><td>站在機器領地內點擊一鍵提交機器審核 (<code>/machine apply</code>)，查看 T2/T3 免領地費狀態。</td></tr><tr><td>🛠️ <code>Slot 34</code></td><td><strong>管理員 (OP) 控制台</strong></td><td><em>(僅 OP 可見)</em> 一鍵開啟全服玩家/假人 <code>/invsee</code> 選擇器、機器認證審核面板與 7z 手動地圖備份。</td></tr></tbody></table><hr><h2 id="⭐-特色與指令相容性" tabindex="-1">⭐ 特色與指令相容性 <a class="header-anchor" href="#⭐-特色與指令相容性" aria-label="Permalink to &quot;⭐ 特色與指令相容性&quot;">​</a></h2><ol><li><strong>即點即觸發 (Instant Action)</strong>： 在子選單中點擊家園或地標，即時觸發傳送；點擊稱號即時切換頭頂標籤；點擊假人即時開啟背包，無需手動輸入繁瑣參數。</li><li><strong>完整指令保留 (Full Command Compatibility)</strong>： 所有原版文字指令（如 <code>/shop</code>, <code>/claim</code>, <code>/home</code>, <code>/warp</code>, <code>/bounty</code>, <code>/treasure</code>, <code>/title</code>, <code>/invsee</code>, <code>/bot</code> 等）皆 100% 完整保留，習慣打字的玩家依然可以隨時鍵入指令！</li></ol>`,13)])])}const g=e(d,[["render",n]]);export{u as __pageData,g as default};
